40	// Encodes a document body as raw UTF-8 bytes and proves the round trip is
41	// lossless. A body carrying unpaired surrogates (which JSON text can express
42	// via "\uD800" escapes) cannot be represented as standalone UTF-8, so it is
43	// rejected instead of silently turning into U+FFFD.
44	function encodeBody(body) {
45	  const bytes = Buffer.from(body, 'utf8');
46	  let decoded;
47	  try {
48	    decoded = fatalDecoder.decode(bytes);
49	  } catch {
50	    throw invalidMarkdown('document body cannot be encoded as UTF-8');
51	  }
52	  if (decoded !== body) throw invalidMarkdown('document body cannot be encoded as UTF-8 losslessly');
53	  return bytes;
54	}
