const FENCE_OPEN_PATTERN = /^ {0,3}(`{3,}|~{3,})[ \t]*([^\n]*)$/u;
const FENCE_CLOSE_PATTERN = /^ {0,3}([`~])\1{2,}[ \t]*$/u;

// Scans a Markdown body for valid [[id]] references appearing in ordinary
// prose. References inside fenced code blocks and inline code spans are only
// stored as literal text, and a reference immediately preceded by an odd run
// of backslashes is escaped. LF and CRLF line endings parse identically.
export function linksFrom(body) {
  const text = String(body);
  const targets = [];
  const lines = text.split('\n');
  let fence = null; // { marker, length } while inside a fenced code block

  for (let li = 0; li < lines.length; li += 1) {
    // A trailing carriage return belongs to a CRLF line ending; strip it so
    // both newline styles parse the same. It is never a fence marker.
    const line = lines[li].endsWith('\r') ? lines[li].slice(0, -1) : lines[li];

    if (fence) {
      const close = FENCE_CLOSE_PATTERN.exec(line);
      if (close && close[1] === fence.marker && close[0].match(/[`~]/u).index >= 0
        && countLeadingMarker(close, fence.marker) >= fence.length) {
        fence = null;
      }
      continue;
    }

    const open = FENCE_OPEN_PATTERN.backtick ? null : FENCE_OPEN_PATTERN.exec(line);
    if (open) {
      fence = { marker: open[1][0], length: open[1].length };
      continue;
    }

    scanProse(line, targets);
  }
  return targets;
}

function countLeadingMarker(match, marker) {
  const run = match[0].match(new RegExp(`(${marker}+)`, 'u'));
  return run ? run[1].length : 0;
}

// Parses one line known to be outside any fenced block. Tracks inline code
// spans (matching backtick runs may span multiple physical lines, so the
// caller threads the pending span between lines) and backslash escapes.
function scanProse(line, targets) {
  const chars = Array.from(line);
  let i = 0;
  while (i < chars.length) {
    const char = chars[i];
    if (char === '`') {
      const run = runLength(chars, i, '`');
      // The opening run can only be closed by an equal-or-longer run in
      // CommonMark; require an exactly matching run per the workspace rules
      // (shorter or longer runs inside do not end the span).
      const end = findClosingRun(chars, i + run, run);
      if (end >= 0) {
        i = end + run;
        continue;
      }
      // No matching closing run: the opening run is ordinary text. Keep
      // scanning from the character after it so later references still
      // count, but it cannot be part of an escape run.
      i += run;
      continue;
    }
    if (char === '[') {
      const target = readReference(chars, i);
      if (target) {
        if (!isEscaped(chars, i)) targets.push(target);
        i += 2 + target.length + 2;
        continue;
      }
    }
    i += 1;
  }
}

// Inline code spans may span newlines; this handles the span state across
// the full body instead of per line.
