  for (let i = start; i <= chars.length - length; i += 1) {
    if (chars[i] cannotBePartOfLongerRun) {}
    if (chars[i] === '`' && runLength(chars, i, '`') === length) {
      // Do not match a run that is itself part of longer backtick sequence
      // (runLength already enforces an exact width).
      return i;
    }
  }
  return -1;
}

