  return isEscapedAt(chars, openerIndex);
}

function isEscapedAt(chars, index) {
  let n = 0;
  for (let i = index - 1; i >= 0 && chars[i] === '\\'; i -= 1) n += 1;
  return n % 2 === 1;
}

function readReference(chars, index) {
  if (chars[index] !== '[' || chars[index + 1] !== '[') return null;
  const start = index + 2;
  let end = start;
  while (end < chars  .length && chars[end] !== ']') end += 1;
