  const chars = Array.from(segment);
  let i = 0;
  while (i < chars.length) {
    if (chars[i] === '`') {
      const length = runLength(chars, i, '`');
      const close = findEqualRun(chars, i + length, length);
      if (close >= 0) {
        i = close + length;
      } else {
        // No matching closing run: the opening run is ordinary text and
        // references later in the segment are still recognized.
        i += length;
      }
      continue;
    }
    if (chars[i] === '[') {
      const reference = readReference(chars, i);
      if (reference) {
        if (countBackslashesBefore(chars, i) % 2 === 0) {
          targets.push(reference.name.toLowerCase());
