  let n = 0;
  while (start + n < chars.length && chars[start + n] === marker) n += 1;
  return n;
}

// Finds the first backtick run after `start` whose width equals `length`;
// runs of other widths are skipped wholesale (they cannot be the closer).
function findEqualRun(chars, start, length) {
  let i = start;
  while (i < chars.length) {
    if (chars[i] === '`') {
      const n = runLength(chars, i, '`');
      if (n === length) return i;
      i += n;
    } else {
      i += 1;
    }
